    where(fc: FilterClosure<TFull>): this;
    /**
     * Метод позволяет пропустить заданное количество обновляемых элементов.
     *
     * @param n Количество элементов, которое необходимо пропустить.
     *
     * Например, при работе с большим количеством элементов приложения
     * можно разбить обновление на порции и динамически определять начало выборки.
     * ```typescript
     * Context.data.from += 100;
     * const rows = await Application.batch()
     *     .update()
     *     .set('str', _ => 'test')
     *     .from(Context.data.from)
     *     .where((f, g) => g.and (
     *         f.__deletedAt.eq(null),
     *         f.str.eq(null)
     *     ))
     *     .all();
     * ```
     */
    from(n: number): this;
    /**
     * Метод позволяет задать ограничение количества обновляемых элементов.
     *
     * @param n Размер выборки (по умолчанию 10, максимум 10000).
     * ```typescript
     * const rows = await Application.batch()
     *     .update()
     *     .set('str', _ => 'test')
     *     .size(500)
     *     .where((f, g) => g.and (
     *         f.__deletedAt.eq(null),
     *         f.str.eq(null)
     *     ))
     *     .all();
     * ```
     */
    size(n: number): this;
    /**
     * Метод выполняет массовое обновление.
     *
     * Возвращает количество действительно обновлённых элементов согласно [[ApplicationBatchUpdater.size]],
     * начиная с [[ApplicationBatchUpdater.from]].
     *
     * По умолчанию количество обновляемых элементов ограничено 10 записями. Если нужно обновить больше элементов,
     * используйте метод [[ApplicationBatchUpdater.size]].
     *
     * ```typescript
     * const searchResults = await Application.update()
     *     .set('str', _ => 'test')
     *     .where((f, g) => g.and (
     *         f.__deletedAt.eq(null),
     *         f.str.eq(null)
     *     ))
     *     .all();
     * ```
     */
